toolCalls.command:
/bin/zsh -lc "node - <<'NODE'
const fs=require('fs');
const s=fs.readFileSync('codenet_p03480_1.obf.js','utf8');
const checks={
 stringArray:/\\[["'^'"\\]]{0,200}(?:'["'^'"']*'|\"["'^"]*")[''^'"\\]]{0,200}\\]/.test(s),
 hexEscapes:(s.match(/\\\\x[0-9a-fA-F]{2}/g)||[]).length,
 unicodeEscapes:(s.match(/\\\\u[0-9a-fA-F]{4}/g)||[]).length,
 evalCalls:(s.match(/\\beval\\s*\\(/g)||[]).length,
 functionCount:(s.match(/\\bfunction\\b/g)||[]).length,
 arrowCount:(s.match(/=>/g)||[]).length,
 whileCount:(s.match(/\\bwhile\\b/g)||[]).length,
 switchCount:(s.match(/\\bswitch\\b/g)||[]).length,
 varCount:(s.match(/\\bvar\\b/g)||[]).length,
 letCount:(s.match(/\\blet\\b/g)||[]).length,
 constCount:(s.match(/\\bconst\\b/g)||[]).length,
 length:s.length,
 lines:s.split(/\\r?\\n/).length
};
console.log(JSON.stringify(checks));
NODE"

/bin/zsh -lc "terser codenet_p03480_1.obf.js --compress --format beautify,comments=false -o deobfuscated/codenet_p03480_1.obf.js && node --check deobfuscated/codenet_p03480_1.obf.js && wc -c deobfuscated/codenet_p03480_1.obf.js && node - <<'NODE'
const fs=require('fs');
const s=fs.readFileSync('deobfuscated/codenet_p03480_1.obf.js','utf8');
console.log(JSON.stringify({hexEscapes:(s.match(/\\\\x[0-9a-fA-F]{2}/g)||[]).length,functions:(s.match(/\\bfunction\\b/g)||[]).length,while:(s.match(/\\bwhile\\b/g)||[]).length,switches:(s.match(/\\bswitch\\b/g)||[]).length,lines:s.split(/\\r?\\n/).length}));
NODE"

